"""Supplier working reserves, fresh-output priority, risky forecasts and deadline discipline."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import hashlib,json
source=(ROOT/'assets/game.js').read_text();sha=hashlib.sha256(source.encode()).hexdigest()
probe=r'''
window.__contractCase=seed=>{__townTest.reset('settlement',seed);G.autoBuild=false;G.policy.privateServices=0;const f=G.firms.find(f=>f.kind==='fishery'),m=OUTSIDE_MARKETS.find(m=>m.id==='port'),s=ensureRegionalTrade(),total=totalMoney();
 // Controlled observed-sales signal; no cash, stock, staff or production granted.
 f.salesTrend=20;const initial=f.stock.food,reserve=regionalContractReserve(f,'food'),q=regionalQuote(f,m,'food','export'),c={id:++s.serial,name:'Working-stock test',firm:f.id,market:m.id,good:'food',quantity:80,delivered:0,price:regionalMarketQuote(m,'food','exports')*1.08,deadline:G.day+30,status:'active'};s.contracts.push(c);dispatchRegionalContracts();const sent=s.shipments.filter(o=>o.contract===c.id).reduce((n,o)=>n+o.qty,0);if(Math.abs(sent-Math.min(80,Math.max(0,initial-reserve)))>.001)throw Error('Supplier reserve not respected');
 __townTest.step(45);if(c.status!=='fulfilled')throw Error('Fresh production never assigned to promise: '+JSON.stringify(c));const plan=regionalContractForecast(f,m,'food',1000000);if(!plan.risk||plan.suggested>=plan.ceiling||plan.dispatchDays>=30)throw Error('Impossible promise shown feasible');
 const impossible={...c,id:++s.serial,name:'Too late',quantity:1000,delivered:0,deadline:G.day+1,status:'active'};s.contracts.push(impossible);dispatchRegionalContracts();if(s.shipments.some(o=>o.contract===impossible.id))throw Error('Known-late new cargo dispatched');__townTest.step(3);if(impossible.status!=='missed')throw Error('Risk erased');
 const saved=JSON.stringify(G),bad=JSON.parse(saved);bad.firms[f.id].productionTrend=-1;if(hydrateSave(bad))throw Error('Negative forecast accepted');if(JSON.stringify(G)!==saved)throw Error('Rejected forecast changed city');const v=validateTown(),err=Math.max(...goodsBalance().map(r=>Math.abs(r.error)));if(!v.ok||Math.abs(totalMoney()-total)>.001||err>.001)throw Error('Contract broke books');return{seed,initial,reserve,sentBeforeProduction:sent,delivered:c.delivered,status:c.status,riskyEstimate:plan.estimate,riskySuggested:plan.suggested,impossible:impossible.status,cashDrift:totalMoney()-total,goodsError:err};};
'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':844,'height':390});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();rows=[p.evaluate('s=>__contractCase(s)',s) for s in [42,101,909]];p.locator('#panelClose').click();p.locator('[data-panel=economy]').click();assert 'Estimated deliverable' in p.locator('#panelBody').inner_text();p.locator('[data-trade-offer]:not([disabled])').first.click();assert 'BEFORE ordinary regional and local wholesale' in p.locator('#eventText').inner_text();p.screenshot(path=str(ROOT/'reports/development-8.0/contract-size-review.png'));assert not errors,errors;b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
(ROOT/'reports/development-8.0/contract-feasibility.json').write_text(json.dumps({'source_sha256':sha,'controlledSalesSignalOnly':True,'rows':rows,'errors':errors},indent=2)+'\n');print('PASS supplier reserve/fresh-output priority/three seeds/explicit impossible forecast/deadline failure/cash/goods/atomic save/real preview',rows)
